// Prueft Eingaben und normalisiert die Rufnummer. Die CRM-Quelle kommt
// ausschliesslich aus der Kunden-Config - dieser Workflow kennt keine
// eigenen Kundendaten.
const e = $input.first().json;
const p = e.params || {};
const c = e.config || {};

// Nur Ziffern und fuehrendes + behalten, damit der Abgleich stabil ist.
function normTelefon(t) {
  let s = String(t || '').trim().replace(/[^0-9+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (s.startsWith('0')) s = '+49' + s.slice(1);
  return s;
}

const telefon = normTelefon(p.telefon || p.from_number || e.from_number);
let fehler = '';
if (!telefon) fehler = 'telefon fehlt';
else if (c.crm_typ === 'none' || !c.crm_typ) fehler = 'kein crm konfiguriert';
else if (!c.crm_quelle) fehler = 'crm quelle fehlt';

return [{ json: Object.assign({}, e, {
  telefon: telefon,
  telefon_kurz: telefon.slice(-9),   // fuer Sheets-Vergleiche ohne Laendervorwahl
  fehler: fehler,
}) }];

// Baut die Antwort fuer alle drei Zweige (Sheet, HTTP, kein CRM).
// Der Kontext kommt aus "Eingaben pruefen", weil die CRM-Nodes das Item ersetzen.
const ktx = $('Eingaben pruefen').first().json;

// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

if (ktx.fehler) {
  // Kein CRM konfiguriert ist kein Absturz: der Agent behandelt den Anrufer
  // dann einfach als unbekannt.
  return [{ json: antwort(true, { ist_bekannt: false, kundenstatus: 'unbekannt',
    letztes_anliegen: '', vorgeschichte_notiz: '' }, ktx.fehler) }];
}

const items = $input.all().map(i => i.json).filter(Boolean);
let treffer = null;

if (ktx.config.crm_typ === 'sheets') {
  // Im Sheet wird ueber die letzten 9 Ziffern verglichen, damit
  // 0170..., +49170... und 0049170... denselben Kontakt finden.
  const ziel = ktx.telefon_kurz;
  treffer = items.find(z => {
    const felder = [z.telefon, z.Telefon, z.telefonnummer, z.Telefonnummer, z.phone];
    return felder.some(f => f && String(f).replace(/[^0-9]/g, '').slice(-9) === ziel.replace(/[^0-9]/g, '').slice(-9));
  }) || null;
} else {
  const r = items[0] || {};
  if (r.error || (r.statusCode && r.statusCode >= 400)) {
    return [{ json: antwort(false, {}, 'crm nicht erreichbar') }];
  }
  const b = r.body || r;
  treffer = (b && (b.kontakt || b.data || (Array.isArray(b) ? b[0] : null))) || null;
  if (treffer && Array.isArray(treffer)) treffer = treffer[0] || null;
}

if (!treffer) {
  return [{ json: antwort(true, { ist_bekannt: false, kundenstatus: 'neu',
    letztes_anliegen: '', vorgeschichte_notiz: '' }, 'kein treffer') }];
}

return [{ json: antwort(true, {
  ist_bekannt: true,
  name: String(treffer.name || treffer.Name || ''),
  kundenstatus: String(treffer.kundenstatus || treffer.Kundenstatus || 'bestand'),
  letztes_anliegen: String(treffer.letztes_anliegen || treffer['Letztes Anliegen'] || ''),
  vorgeschichte_notiz: String(treffer.notiz || treffer.Notiz || ''),
}, 'kontakt gefunden') }];
